INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('8ec245fe-d576-436a-b8e9-122a4d33911a','Crecimiento sin Expansión Estatal: La Educación Superior no Universitaria en CABA','Informe','OPER','2026-10-30T03:00:00.000Z','https://drive.google.com/file/d/1k7C8Z81s6IcVhDoWGGVOr_EX7JLQmJPr/view?usp=drivesdk','La educación superior no universitaria en la Ciudad crece… pero el Estado no acompaña.' || char(10) || 'Desde 2014, la matrícula estatal dependiente del GCBA prácticamente no creció (+0,3%), mientras la privada aumentó 15,2%. De los 12.064 estudiantes que sumó el sistema entre 2019 y 2025, sólo 897 fueron al sector estatal.' || char(10) || 'Al mismo tiempo, la formación docente perdió más de una quinta parte de su matrícula, justo donde el Estado forma a 3 de cada 4 futuros docentes.',0,'2026-10-30T15:09:33.119Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('ffdaa85e-63a6-4216-bc58-ac116db6ad3c','ANDIS y Auditorías a Pensiones No Contributivas por Discapacidad','Informe','OPER','2025-12-02T03:00:00.000Z','https://drive.google.com/file/d/1kKzJztxJ6M6wTEgBlCvjhRfWX5maW-s1/view?usp=drivesdk','Análisis las auditorías de ANDIS a las pensiones no contributivas por discapacidad, en las que se citó al 81% de los titulares aunque solo el 45% de las notificaciones llegó a destino. El informe denuncia violaciones al debido proceso y a la Convención sobre los Derechos de las Personas con Discapacidad, y detalla las vías legales para defenderse ante una suspensión.',0,'2026-09-23T14:59:28.263Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('f0eea1f6-f225-41b7-898a-3dce01ec5b70','Más que LEFI','Informe de coyuntura','CEER','2025-08-01T03:00:00.000Z','https://drive.google.com/file/d/1ZYBntxGFSe4GqqeK_JagTpCvvruzJO7l/view?usp=drivesdk','La volatilidad de las últimas dos semanas no puede entenderse sin la daga al corazón del programa monetario que implicó la rápida expansión monetaria al cancelar las LEFI.',0,'2026-09-19T00:48:10.038Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('8f7f10a8-5bd3-4845-ab96-3474004920ba','FRENESÍ ELECTORAL: ¿CUESTE LO QUE CUESTE?','Informe de coyuntura','CEER','2025-09-02T03:00:00.000Z','https://drive.google.com/file/d/1R_Kv8-_8WyafWoNAN0c-AKoSs013visV/view?usp=drivesdk','El gobierno se enfrenta a las urnas entre escándalos de corrupción, estancamiento económico y desorden financiero. Pierde la herramienta de ganar elecciones: el salario real.',0,'2026-09-19T00:47:23.095Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('09a1e091-ada5-4ec1-a5ad-f2897dbe0ac5','FIN DEL CEPO Y ACUERDO CON EL FMI: El nuevo programa económico','Informe Especial','CEER','2025-12-01T03:00:00.000Z','https://drive.google.com/file/d/1ZZ4i6wpXMPfadFlYpNsUgRN9QxLljn0M/view?usp=drivesdk','¿POR QUÉ OTRA VEZ AL FONDO? Con reservas netas negativas y sin acceso a financiamiento privado, el gobierno recurre al FMI para sostener el programa y la campaña electoral.',0,'2026-09-19T00:44:58.607Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('2427f08f-c38a-4266-84ed-269e1e06cee6','PRIMERA REVISIÓN DEL FMI: Amigos son los amigos.','Informe Especial','CEER','2025-09-01T03:00:00.000Z','https://drive.google.com/file/d/1uWqttII_wWprJEZjbSpsqx4LIJgDgg6z/view?usp=drivesdk','A pesar de incumplir la meta de reservas netas por 3500 millones de dólares, el Fondo perdonó al gobierno y destrabó un nuevo desembolso. Sin embargo, lo hizo con múltiples críticas al rumbo económico.',0,'2026-09-19T00:43:58.948Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('885a12b9-334b-4485-ab50-3f5d7b25b9d8','COMPRÁ, CAMPEÓN.','Informe Especial','CEER','2025-09-01T03:00:00.000Z','https://drive.google.com/file/d/1d4MFqMzHTs51nwzhRghi-vLLy1IDifMo/view?usp=drivesdk','Tras la derrota electoral en PBA, el gobierno se vio obligado a intervenir el dólar financiero y bajar las tasas de interés. La estrategia de defender el techo de la banda cambiaria está poniendo en duda la sostenibilidad de la deuda externa en el corto plazo.',0,'2026-09-19T00:42:24.226Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('99fdb64e-cfa6-4a67-8136-20c953d8632a','DOCENTES EN FUGA','Informe','OPER','2025-11-01T03:00:00.000Z','https://drive.google.com/file/d/1b-wcyLzOk88yvsyS34RXqb4VcGP0yBV2/view?usp=drivesdk','Una crisis silenciosa en la edudación porteña.',0,'2026-09-19T00:38:10.880Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('ae81402f-3a4c-4619-a992-18c525424aef','Guía al Año Electoral 2025 en Argentina','Informe','OPAL','2025-02-01T03:00:00.000Z','https://drive.google.com/file/d/1ClcQZiUqb7k4sEXFqJ5xi_Tt-gVPtG3q/view?usp=drivesdk','Monitoreo preliminar del estatus político-social del país en vísperas del año electoral, incluyendo un análisis de los cargos en juego.',0,'2026-09-19T00:36:44.444Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('6c05c658-232d-466e-bee4-f8d4c55d5408','Narrativas sobre el voto popular en crisis. Milei y el mito del voto marginal','Informe','OPAL','2025-09-01T03:00:00.000Z','https://drive.google.com/file/d/1IK_utiGxiPUMtBcq3bdkv8OBCPefk1Aw/view?usp=drivesdk','Trabajo sobre la hipótesis de que "las comunas pobres de CABA votaron a Milei en 2023" y la reconfiguración de las narrativas en torno al voto popular en crisis.',0,'2026-09-19T00:35:58.934Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('5bbe08d3-0ebd-4fb7-b905-ca3490a84c6f','Un Nuevo Poder Legislativo. La subtrama de la división de poderes','Informe','OPAL','2025-09-01T03:00:00.000Z','https://drive.google.com/file/d/1BVeVPxMUqwRbhyMNgYWXSz4vAJa6JmMR/view?usp=drivesdk','Análisis sobre los escenarios de la nueva composición del Poder Legislativo y cómo impactará en el equilibrio de fuerzas y la dinámica de la división de poderes.',0,'2026-09-19T00:35:10.624Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('12dcdfbd-d4f9-4878-9888-dbf27e932f2e','NÚMEROS GORDOS: NO PASA NADA','Informe','OPAL','2025-10-01T03:00:00.000Z','https://drive.google.com/file/d/1F8KoqWFeG677-aTijaFUz1NK3yUGmTvG/view?usp=drivesdk','Análisis de coyuntura sobre las grandes cifras que impactan el tablero político y social, desmitificando percepciones y confirmando tendencias clave.',0,'2026-09-19T00:33:13.302Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('71cc17ae-3b85-49a5-ac05-e43fda36be64','Más allá del clientelismo. La integración socio-urbana como política de co-responsabilidad y gestión colectiva','Informe Especial','OPSA','2025-12-01T03:00:00.000Z','https://drive.google.com/file/d/1sRAm6dJc-6bKvAEF2R5hyvFOndYO2TL5/view?usp=drivesdk','En este primer informe definimos qué es el clientelismo y cómo se expresa en la realidad de los barrios populares. Estudiamos el panorama actual frente a la eliminación de políticas -el FISU- que no reproducen mecanismos clientelares tradicionales, y que efectivamente promueven nuevas formas de articulación basadas en la co-responsabilidad, la gestión colectiva y la ampliación de derechos ciudadanos.',0,'2026-09-19T00:30:56.052Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('00a69880-aa6c-49fa-bf65-a946243c049c','Mes de la Memoria','Informe','CEDHyS','2025-03-24T03:00:00.000Z','https://drive.google.com/file/d/1vZpjkCd8MKYKMRR_SdTMIpARrEh5UNtN/view?usp=drivesdk','Nunca más.',0,'2026-09-19T00:28:44.269Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('5348b78f-2bf0-4dcf-acc9-b1bddd7c1bd2','Sur Global #1','Revista','CEEIR','2025-12-01T03:00:00.000Z','https://drive.google.com/file/d/1Ow6RYrRxxVTBIG5dSXWp5Ehdqw9nGOUo/view?usp=drivesdk','',0,'2026-05-18T14:28:35.771Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('af54cf7b-677d-43b7-a648-f58550dde997','Informe Malvinas: Experiencias semejantes, antecedentes y resoluciones','Informe','CEEIR','2025-07-01T03:00:00.000Z','https://drive.google.com/file/d/1TZc6tRJp-cl5a6wX7mf-bW-ncnOXH40J/view?usp=drivesdk','La cuestión de las Islas Malvinas no puede entenderse de forma aislada ni reducida a un diferendo territorial bilateral. El presente informe propone analizar cuál de los principios -autodeterminación de los pueblos o integridad territorial- resulta más favorable para la recuperación de las Islas Malvinas.',0,'2026-05-18T14:07:16.305Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('3d3f9500-ee38-4a7a-8f56-77a07e370c16','Instituto Nacional de Servicio al Exterior: Una propuesta soberana','Informe','CEEIR','2025-08-01T03:00:00.000Z','https://drive.google.com/file/d/19boHn99bWYco3nnO-_NgixBnmY4z6sao/view?usp=drivesdk','El Instituto del Servicio Exterior de la Nación tiene como principal objetivo encargarse de la formación e instrucción de todo aquél que posea un título de grado y desee dedicarse por completo a la vida diplomática. El presente informe fue pensado y elaborado para dar respuesta a las diversas políticas de gobierno del actual presidente Javier Milei en relación al servicio diplomático de la Nación.',0,'2026-05-18T14:02:04.225Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('fafe906d-d0fb-44dc-847d-c0d6a919a2fc','El litio como factor geopolítico estratégico en Argentina y América Latina','Informe','CEEIR','2026-02-01T03:00:00.000Z','https://drive.google.com/file/d/1-rgubTEmJFj7UiiYLhthX1bP-0hr4hcI/view?usp=drivesdk','',0,'2026-05-18T13:57:32.805Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('7903c0f6-b30b-466d-9f00-7f7470f5e316','Cooperación entre Argentina y Brasil en Proyectos de Infrasestructura y Corredores Bioceánicos','Informe','CEEIR','2026-01-01T03:00:00.000Z','https://drive.google.com/file/d/1iShR9ynxMvL6oAZEhLBwskXrhPxaKR0b/view?usp=drivesdk','La importancia de esta cooperación no se limita a los aspectos materiales de la infraestructura. Se trata de una apuesta estratégica que refleja una visión común de desarrollo e integración, en la cual la complementariedad entre ambas economías adquiere una dimensión geopolítica significativa.',0,'2026-05-18T13:23:12.752Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('cef0f1f3-bde6-4bd7-9108-2a25d2c69752','La reforma laboral','Informe Especial','CEER','2025-12-18T03:00:00.000Z','https://drive.google.com/file/d/1F2hR3B8FBFi0yayNb3Pgz-RX_f3vT8w3/view?usp=drivesdk','El gobierno envió al congreso la reforma laboral. Incluso si ignoramos el atraso en materia de derechos, ¿la reforma tiene sentido económico? ¿flexibilizar es igual a crear empleos?',0,'2026-05-15T17:08:43.708Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('90e0319c-2e1a-499e-bfa8-bdd1547e43f3','Los cambios en la reforma laboral','Informe Especial','CEER','2026-02-20T03:00:00.000Z','https://drive.google.com/file/d/1bDPSVnvaptBveJ9zCPn_9jkDteTYWP8o/view?usp=drivesdk','La reforma laboral está (casi) aprobada, incluyendo su punto más fuerte: los FAL. Los nuevos fondos, previstos para el pago de indemnizaciones, sufrieron cambios en el Congreso: ¿van a funcionar? No estamos seguros. ',0,'2026-05-15T17:06:58.093Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('025c156b-1d39-4ace-ba61-6f829c86ecdc','¿Baja la pobreza?','Informe Especial','CEER','2026-04-02T03:00:00.000Z','https://drive.google.com/file/d/1mTczaZOdYll2oIOmvQF9jahuwTm3qJgp/view?usp=drivesdk','El INDEC difundió la pobreza del segundo semestre de 2025: 29,2%, más de 10% por debajo de 2023. Pero, ¿en serio bajó?',1,'2026-05-15T17:04:40.927Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('5aaf3482-844b-4ae1-868c-019902447c56','Entre la banda y la pared','Informe de coyuntura','CEER','2026-01-24T03:00:00.000Z','https://drive.google.com/file/d/14bbNtOvKcKAIDbs0ykCcXs6oYmOecgTZ/view?usp=drivesdk','Entre la banda y la pared: dólar presionado, reservas frágiles, inflación que no baja del 2% y una deuda en pesos que vuelve a tensar al sistema financiero. El gobierno ganó las elecciones, pero los problemas macro siguen ahí. ',0,'2026-05-15T17:01:40.909Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('90715bc0-7ab2-419d-bb75-13520a75c41c','Vínculos de Cooperación Nuclear entre Argentina y Francia','Informe','CEEIR','2025-12-01T03:00:00.000Z','https://drive.google.com/file/d/10HImBLU07N6c8lKlrwi2pnud9MJSHFti/view?usp=drivesdk','El presente informe aborda la cooperación entre Argentina y Francia en materia de energía nuclear, atendiendo a las dimensiones historica, económica y ambiental. Entendiendo que la energía nuclear es una cuestión central en el marco de la transición energética, y que su comercialización es asunto de política internacional, el objetivo de este informe es plasmar los avances destacados en cooperación es dicha materia entre dos Estados cuya relación histórica ha dado grandes frutos.',0,'2026-05-15T13:39:56.818Z');
INSERT OR REPLACE INTO reports (id,titulo,tag,centro,fecha,pdf_url,descripcion,destacado,created_at) VALUES ('c1bf48cf-b3a2-4a6b-9a3c-80d6d2113e83','Cooperación Antártica entre Argentina y Chile en vistas de la renegociación del  Tratado Antártico','Informe','CEEIR','2025-11-01T03:00:00.000Z','https://drive.google.com/file/d/11wEiuf-BefvHzjKEpFWanfzx4tNHK0Nv/view?usp=drivesdk','Desde mediados del siglo XX, Argentina y Chile han desarrollado una cooperación constante en materia antártica. En este informe se destaca la importancia del trabajo técnico continuo entre ambos Estados para alcanzar un marco de reclamo conjunto que explore las vastas potencialidades de la región, abarcando dimensiones logísticas, científicas, ambientales y económicas.',0,'2026-05-15T13:18:03.406Z');
